import React from "react";

function BottomNav({ active }) {
    const navItems = [
        { id: "home", label: "Home", icon: "home", link: "/home" },
        { id: "cities", label: "Cities", icon: "explore", link: "/cities" },
        { id: "chat", label: "Chat", icon: "chat_bubble", link: "/chat" },
        { id: "profile", label: "Profile", icon: "person", link: "/profile" },
    ];

    const navWrapperStyle = {
        position: "fixed",
        bottom: "20px", // Floating off the bottom
        left: "50%",
        transform: "translateX(-50%)",
        width: "90%", // Doesn't touch the edges
        maxWidth: "400px",
        display: "flex",
        justifyContent: "space-around",
        padding: "12px 10px",
        background: "rgba(255, 255, 255, 0.85)", // Glass effect
        backdropFilter: "blur(10px)", // Blur background
        borderRadius: "24px",
        boxShadow: "0 10px 25px rgba(0,0,0,0.1)",
        border: "1px solid rgba(255,255,255,0.3)",
        zIndex: 1000,
    };

    const itemStyle = (isActive) => ({
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        textDecoration: "none",
        padding: "8px 16px",
        borderRadius: "16px",
        transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
        background: isActive ? "#a8232415" : "transparent", // Subtle highlight background
        color: isActive ? "#a82324" : "#94a3b8",
        gap: "4px",
    });

    return (
        <div style={navWrapperStyle}>
            {navItems.map((item) => {
                const isActive = active === item.id;
                return (
                    <a key={item.id} href={item.link} style={itemStyle(isActive)}>
                        <span
                            className="material-icons-round"
                            style={{
                                fontSize: "24px",
                                transform: isActive ? "scale(1.1)" : "scale(1)",
                                transition: "transform 0.2s ease"
                            }}
                        >
                            {item.icon}
                        </span>
                        <span style={{
                            fontSize: "11px",
                            fontWeight: isActive ? "700" : "500",
                            opacity: isActive ? 1 : 0.8
                        }}>
                            {item.label}
                        </span>
                    </a>
                );
            })}
        </div>
    );
}

export default BottomNav;
